    private function formatMoneyFromCents(int $cents, string $currencyCode): string
    {
        $currencyCode = strtoupper(trim($currencyCode));
        if ($currencyCode === '') {
            $currencyCode = 'AUD';
        }

        $prefix = match ($currencyCode) {
            'USD' => '$',
            'GBP' => '£',
            'EUR' => '€',
            'AUD' => 'A$',
            default => $currencyCode.' ',
        };

        return $prefix.number_format($cents / 100, 2, '.', ',');
    }
}

